# --- exact Fraction reference ----------------------------------------------

def _reference(reports, layers):
    parsed = {
        name: json.loads(report) for name, report in reports.items()
    }
    alpha = Fraction(str(next(iter(parsed.values()))["alpha"]))
    identities = [
        (tuple(group["pick"]), item["factor"])
        for group in next(iter(parsed.values()))["groups"]
        for item in group["items"]
    ]
    values = {}
    for name, payload in parsed.items():
        for group in payload["groups"]:
            pick = tuple(group["pick"])
            for item in group["items"]:
                values[(name, pick, item["factor"])] = (
                    Fraction(str(item["effect"])),
                    item["reject"],
                )

    groups = []
    for layer in _LAYERS:
        labels = sorted({layers[name][_LAYERS.index(layer)]
                         for name in reports})
        for label in labels:
            members = [
                name for name in reports
                if layers[name][_LAYERS.index(layer)] == label
            ]
            items = []
            for pick, factor in sorted(
                identities,
                key=lambda identity: (
                    identity[0], _FACTORS.index(identity[1])
                ),
            ):
                effects = [
                    values[(name, pick, factor)][0] for name in members
                ]
                rejects = [
                    values[(name, pick, factor)][1] for name in members
                ]
                n = len(members)
                mean = sum(effects, Fraction(0)) / n
                if mean < 0:
                    direction = "down"
                    same = sum(1 for effect in effects if effect < 0)
                elif mean > 0:
                    direction = "up"
                    same = sum(1 for effect in effects if effect > 0)
                else:
                    direction = "flat"
                    same = 0
                items.append(
                    {
                        "pick": list(pick),
                        "factor": factor,
                        "n": n,
                        "mean": float(mean),
                        "direction": direction,
                        "consistency": same / n,
                        "significant": sum(1 for r in rejects if r) / n,
                    }
                )
            groups.append({"layer": layer, "key": label, "items": items})
    return {"alpha": float(alpha), "groups": groups}


def _assert_matches_reference(reports, layers):
    out = region_attr_layers(reports, layers)
    payload = json.loads(out)
    expected = _reference(reports, layers)
    assert len(payload["groups"]) == len(expected["groups"])
    for group, exp_group in zip(payload["groups"], expected["groups"]):
        assert group["layer"] == exp_group["layer"]
        assert group["key"] == exp_group["key"]
        assert len(group["items"]) == len(exp_group["items"])
        for item, exp in zip(group["items"], exp_group["items"]):
            assert list(item) == [
                "pick", "factor", "n", "mean", "direction",
                "consistency", "significant",
            ]
            assert item["pick"] == exp["pick"]
            assert item["factor"] == exp["factor"]
            assert item["n"] == exp["n"]
            assert isinstance(item["n"], int) and not isinstance(
                item["n"], bool
            )
            assert item["direction"] == exp["direction"]
            assert abs(item["mean"] - exp["mean"]) < 5.1e-7
            assert abs(item["consistency"] - exp["consistency"]) < 5.1e-7
            assert abs(
                item["significant"] - exp["significant"]
            ) < 5.1e-7
    return out


